int netlink_dump(struct sock *sk) {
    struct sk_buff *skb;
    int err = 0;

    mutex_lock(&sk->sk_lock);
    if (sk->sk_callback_running) {
        mutex_unlock(&sk->sk_lock);
        return -EBUSY;
    }

    if (sk->sk_rcvbuf_used >= sk->sk_rcvbuf) {
        mutex_unlock(&sk->sk_lock);
        return -ENOBUFS;
    }

    skb = alloc_skb(NETLINK_HDRLEN, GFP_KERNEL);
    if (!skb) {
        mutex_unlock(&sk->sk_lock);
        return -ENOMEM;
    }

    sk->sk_rcvbuf_used += skb->truesize;
    skb_set_owner_r(skb, sk);

    err = sk->sk_prot->dump(skb, sk);
    if (err < 0) {
        kfree_skb(skb);
        sk->sk_rcvbuf_used -= skb->truesize;
        mutex_unlock(&sk->sk_lock);
        return err;
    }

    if (sk->sk_filter) {
        skb->sk = sk;
        skb_set_owner_w(skb, sk);
        netlink_unicast(sk, skb, 0);
    } else {
        kfree_skb(skb);
    }

    mutex_unlock(&sk->sk_lock);
    return 0;
}

int netlink_dump(struct sock *sk) {
    struct sk_buff *skb;
    int err = 0;

    mutex_lock(&dump_mutex);
    if (dump_callback_running) {
        mutex_unlock(&dump_mutex);
        return -EBUSY;
    }

    if (sk_rmem_alloc_get(sk) >= sk->sk_rcvbuf) {
        mutex_unlock(&dump_mutex);
        return -ENOBUFS;
    }

    skb = alloc_skb(sk->sk_rcvbuf, GFP_KERNEL);
    if (!skb) {
        mutex_unlock(&dump_mutex);
        return -ENOMEM;
    }

    dump_callback_running = true;
    err = sk->sk_prot->dump(skb, sk);
    if (err < 0) {
        kfree_skb(skb);
        dump_callback_running = false;
        mutex_unlock(&dump_mutex);
        return err;
    }

    if (check_filters(skb)) {
        netlink_send(skb);
    } else {
        kfree_skb(skb);
    }

    dump_callback_running = false;
    mutex_unlock(&dump_mutex);
    return 0;
}

int nl_dump_messages(struct sock *sk) {
    struct sk_buff *skb = NULL;
    int err = 0;

    mutex_lock(&sk->sk_mutex);
    if (sk->sk_callback_running) {
        mutex_unlock(&sk->sk_mutex);
        return -EBUSY;
    }

    if (sk->sk_rcvbuf_used >= sk->sk_rcvbuf) {
        mutex_unlock(&sk->sk_mutex);
        return -ENOBUFS;
    }

    skb = alloc_skb(sk->sk_rcvbuf / 2, GFP_KERNEL);
    if (!skb) {
        mutex_unlock(&sk->sk_mutex);
        return -ENOMEM;
    }

    sk->sk_rcvbuf_used += skb->truesize;
    err = sk->sk_prot->dump(skb, sk);
    if (err < 0) {
        kfree_skb(skb);
        sk->sk_rcvbuf_used -= skb->truesize;
        mutex_unlock(&sk->sk_mutex);
        return err;
    }

    if (sk->sk_filter) {
        skb = sk_filter(sk, skb);
        if (!skb) {
            mutex_unlock(&sk->sk_mutex);
            return 0;
        }
    }

    skb_queue_tail(&sk->sk_receive_queue, skb);
    mutex_unlock(&sk->sk_mutex);

    return 0;
}

